(()=>{'use strict';
const A=RepoAccount,$=s=>document.querySelector(s),URL_='/api/viewer';
let data=null,busy=false;
const preview=RepoViewer.create({fetchEligibility:async()=>({eligible:false})}),live=RepoViewer.create({fetchEligibility:RepoViewer.liveEligibility()});
const when=v=>v?new Date(v).toLocaleString(undefined,{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}):'never';
const reasonText={own_origin:'RepoShelf cannot be a demo',scenario_changed:'Scenario or address edited since the last qualification',global_disabled:'Global switch is off',not_approved:'Not approved',manual_disabled:'Disabled by an administrator',suspended:'Suspended after a failed or inconclusive check',not_https:'Address is not https',no_evidence:'No qualification yet',latest_failed:'Latest qualification failed',latest_inconclusive:'Latest qualification was inconclusive',url_changed:'Address changed since the last qualification',config_changed:'Viewer settings changed since the last qualification',stale:'Qualification is older than 48 hours',ok:'Eligible for the viewer'};
function render(){
 const ws=$('#vw-workspace');ws.hidden=!(A.user?.admin&&data);if(ws.hidden)return;
 $('#vw-enabled').checked=data.enabled===true;$('#vw-config').textContent=`Viewer configuration version ${data.config.version}. Evidence is good for ${data.config.maxEvidenceAgeHours} hours. The viewer runs on ${data.config.viewerOrigin}.`;
 $('#vw-profiles').value=(data.required_profiles||['chromium']).join(', ');
 const soon=(data.demos||[]).filter(d=>d.approved&&!d.manual_disabled&&(!(d.profiles||[]).length||(d.profiles||[]).some(p=>Date.now()-Date.parse(p.checked_at)>36*3600000)));$('#vw-expiry').textContent=soon.length?`${soon.length} approved demo${soon.length===1?'':'s'} ${soon.length===1?'has':'have'} evidence missing or older than 36 hours. Check the Demo viewer qualification workflow: evidence expires at 48 hours.`:'';
 const list=$('#vw-list');list.replaceChildren();
 for(const d of data.demos||[]){
  const li=document.createElement('li'),text=document.createElement('span'),actions=document.createElement('span');
  const flags=[d.allow_popups?'popups':'',d.allow_downloads?'downloads':''].filter(Boolean).join(', ')||'no extras';
  const runs=(d.profiles||[]).map(p=>`${p.browser} ${p.result}${p.reason?' ('+p.reason+')':''} ${when(p.checked_at)}`).join('; ')||'never qualified';
  text.textContent=`${d.project_id} · revision ${d.scenario_revision||1} · ${d.approved?'approved':'not approved'} · ${reasonText[d.eligibility?.reason]||d.eligibility?.reason}${d.eligibility?.profile?' ('+d.eligibility.profile+')':''} · ${runs} · ${flags}${d.manual_disabled?' · disabled: '+(d.manual_disabled_reason||'no reason given'):''}`;
  actions.className='account-actions';
  const unq=document.createElement('button');unq.type='button';unq.className='button outline';unq.textContent='Unqualified preview';unq.setAttribute('aria-label','Open an unqualified preview of '+d.project_id);unq.onclick=()=>preview.open({id:d.project_id,url:d.demo_url,flags:{popups:d.allow_popups,downloads:d.allow_downloads},title:d.project_id,preview:true,opener:unq});
  const vis=document.createElement('button');vis.type='button';vis.className='button outline';vis.textContent='Test as visitor';vis.setAttribute('aria-label','Test '+d.project_id+' as a visitor');vis.onclick=async()=>{$('#vw-list-status').textContent='Checking…';const r=await live.open({id:d.project_id,url:d.demo_url,title:d.project_id,opener:vis});$('#vw-list-status').textContent=r.opened?'Opened exactly as a visitor would get it. It closes if the demo is disabled.':`Not eligible (${reasonText[r.reason]||r.reason}). A visitor would get the demo in a new tab.`};
  const edit=document.createElement('button');edit.type='button';edit.className='button outline';edit.textContent='Edit';edit.setAttribute('aria-label','Edit '+d.project_id);edit.onclick=()=>{$('#vw-project').value=d.project_id;$('#vw-url').value=d.demo_url;$('#vw-scenario').value=JSON.stringify(d.scenario,null,2);$('#vw-popups').checked=d.allow_popups;$('#vw-downloads').checked=d.allow_downloads;$('#vw-approved').checked=d.approved;$('#vw-notes').value=d.notes||'';$('#vw-form').scrollIntoView({block:'start'});$('#vw-project').focus()};
  const toggle=document.createElement('button');toggle.type='button';toggle.className='button outline';toggle.textContent=d.manual_disabled?'Re-enable':'Disable';toggle.setAttribute('aria-label',(d.manual_disabled?'Re-enable ':'Disable ')+d.project_id);toggle.onclick=async()=>{let reason='';if(!d.manual_disabled){reason=prompt('Why is this demo being disabled?','')??null;if(reason===null)return}await post('disable',{project:d.project_id,disabled:!d.manual_disabled,reason},'#vw-list-status')};
  actions.append(unq,vis,edit,toggle);
  for(const p of (d.profiles||[]).filter(x=>x.result!=='ok')){const clear=document.createElement('button');clear.type='button';clear.className='button outline';clear.textContent='Clear '+p.browser;clear.setAttribute('aria-label','Clear the '+p.browser+' result for '+d.project_id);clear.onclick=async()=>{if(confirm(`Forget the ${p.browser} result for ${d.project_id}? Only do this if that browser profile is being retired.`))await post('clear-profile',{project:d.project_id,browser:p.browser},'#vw-list-status')};actions.append(clear)}
  li.append(text,actions);list.append(li)}
 if(!(data.demos||[]).length){const li=document.createElement('li');li.textContent='No demos have been added yet.';list.append(li)}
}
async function loadMine(){const status=$('#vw-my-preview-status');try{const r=await A.request(URL_+'?action=my-preview');$('#vw-my-preview').checked=r.preview===true;status.textContent=r.available===false?'This setting is unavailable until migration 23 (202610070023_viewer_admin_preview.sql) has been applied in Supabase.':''}catch(e){status.textContent=e.message}}
$('#vw-my-preview').onchange=async e=>{const box=e.target,status=$('#vw-my-preview-status');status.textContent='';try{const r=await A.request(URL_+'?action=my-preview',{method:'POST',body:JSON.stringify({preview:box.checked})});box.checked=r.preview===true;status.textContent=box.checked?'On. Try demo now opens demos in the viewer for your account. Reload the storefront to apply it.':'Off. Demos open in a new tab.'}catch(err){box.checked=!box.checked;status.textContent=err.message.includes('unavailable')?'Could not save. Apply migration 23 (202610070023_viewer_admin_preview.sql) in Supabase first.':err.message}};
async function loadAll(){const status=$('#vw-all-users-status');try{const r=await A.request(URL_+'?action=all-users');$('#vw-all-users').checked=r.allUsers===true;status.textContent=r.available===false?'This setting is unavailable until migration 24 (202610070024_viewer_all_users.sql) has been applied in Supabase.':''}catch(e){status.textContent=e.message}}
$('#vw-all-users').onchange=async e=>{const box=e.target,status=$('#vw-all-users-status');status.textContent='';try{const r=await A.request(URL_+'?action=all-users',{method:'POST',body:JSON.stringify({allUsers:box.checked})});box.checked=r.allUsers===true;status.textContent=box.checked?'On. Try demo now opens demos in the viewer for every visitor. Visitors pick this up within about a minute.':'Off. Every Try demo opens in a new tab again.'}catch(err){box.checked=!box.checked;status.textContent=err.message.includes('unavailable')?'Could not save. Apply migration 24 (202610070024_viewer_all_users.sql) in Supabase first.':err.message}};
async function load(){try{data=await A.request(URL_+'?action=list');$('#vw-gate').hidden=true;render();void loadMine();void loadAll()}catch(e){$('#vw-gate').hidden=false;$('#vw-gate').textContent=e.message}}
async function post(action,body,status){if(busy)return;busy=true;try{$(status).textContent='';await A.request(URL_+'?action='+action,{method:'POST',body:JSON.stringify(body)});await load();$(status).textContent='Saved.'}catch(e){$(status).textContent=e.message}finally{busy=false}}
$('#vw-profiles-save').onclick=async()=>{const profiles=$('#vw-profiles').value.split(',').map(x=>x.trim()).filter(Boolean);await post('settings',{requiredProfiles:profiles},'#vw-switch-status')};
$('#vw-enabled').onchange=async e=>{const box=e.target;await post('settings',{enabled:box.checked},'#vw-switch-status');box.checked=data?.enabled===true};
$('#vw-form').onsubmit=async e=>{e.preventDefault();let scenario;try{scenario=JSON.parse($('#vw-scenario').value)}catch{$('#vw-form-status').textContent='The scenario is not valid JSON.';return}
 await post('save',{project:$('#vw-project').value.trim(),demoUrl:$('#vw-url').value.trim(),scenario,allowPopups:$('#vw-popups').checked,allowDownloads:$('#vw-downloads').checked,approved:$('#vw-approved').checked,notes:$('#vw-notes').value},'#vw-form-status')};
function refresh(){if(!A.ready)return;if(!A.user){$('#vw-gate').hidden=false;$('#vw-gate').textContent='Sign in as an administrator to use this page.';$('#vw-workspace').hidden=true;return}if(!A.user.admin){$('#vw-gate').hidden=false;$('#vw-gate').textContent='Administrator access is required.';$('#vw-workspace').hidden=true;return}void load()}
// The Demo viewer tab of Administration starts this when it is first opened, and again on every later visit to refresh.
let started=false;
window.RepoAdminViewer={start(){if(started){void load();return}started=true;window.addEventListener('reposhelf-account',refresh);refresh()}};
})();
